insert into public.projects(id,title,category,year,subtitle,meta,description,cover,style,images,sort_order,published) values('whitegrain','White Grain','identity',2025,'Identitet vizual & print','Identitet vizual / Print — 2025','Identiteti i studios sonë, i sjellë në letër. Një sistem i përmbajtur grafik ku tipografia, kontrasti dhe materiali ndërtojnë një gjuhë të përbashkët.','assets/business-card-contact.jpg','brand','[["assets/business-card-stack.jpg", "White Grain — kartëvizita dhe materialitet"], ["assets/business-card-contact.jpg", "Sistemi grafik dhe detajet e kontaktit"]]'::jsonb,0,true) on conflict(id) do nothing;
insert into public.projects(id,title,category,year,subtitle,meta,description,cover,style,images,sort_order,published) values('blue','Kioska Blue','space',2025,'Koncept hapësinor & modelim 3D','Koncept hapësinor / Modelim 3D — 2025','Koncept për një kioskë shërbimi me panelim të personalizuar. Ngjyra blu dhe grafika organike lidhin identitetin vizual me strukturën, ndërsa plani eksploron organizimin e hapësirës.','assets/kiosk-blue-render.jpg','kiosk','[["assets/kiosk-blue-render.jpg", "Pamja axonometrike e kioskës"], ["assets/kiosk-blue-plan.jpg", "Planimetria dhe pamjet e projektit"]]'::jsonb,1,true) on conflict(id) do nothing;
insert into public.projects(id,title,category,year,subtitle,meta,description,cover,style,images,sort_order,published) values('atelier','Van Gogh Atelier','space',2024,'Studim interieri & ilustrim arkitekturor','Studim interieri / Ilustrim arkitekturor — 2024','Një interpretim hapësinor i frymëzuar nga atelier-i i Van Gogh. Muret me ngjyra, pikturat dhe shkallët prej druri krijojnë një dialog mes artit dhe hapësirës së punës.','assets/atelier-room-axonom.jpg','atelier','[["assets/atelier-room-axonom.jpg", "Axonometria — organizimi i atelier-it"], ["assets/atelier-section.jpg", "Seksioni — ngjyra, lartësi dhe materiale"], ["assets/atelier-elevation.jpg", "Elevacioni — vizatimi teknik i objekteve dhe mobilimit"]]'::jsonb,2,true) on conflict(id) do nothing;
insert into public.projects(id,title,category,year,subtitle,meta,description,cover,style,images,sort_order,published) values('white','Kioska White','space',2025,'Formë, volum & materialitet','Koncept hapësinor / Studim vëllimor — 2025','Një studim monokrom i konceptit të kioskës. Paleta e bardhë vendos në fokus volumet, hapjet dhe marrëdhënien mes elementeve të strukturës.','assets/kiosk-white-render.jpg','white','[["assets/kiosk-white-render.jpg", "Studimi monokrom i volumeve"]]'::jsonb,3,true) on conflict(id) do nothing;
